pat=re.compile(r'\\bBill C-\\d+\\b',re.I)
found=[]
for p in sorted(glob.glob('articles/2026/*/*/articles.jsonl')):
 try:
  for l in open(p):
   x=json.loads(l); text=(x.get('title') or '')+'\\n'+(x.get('content') or '')
