   if nums and any(w in text.lower() for w in ['canada','canadian','parliament','ottawa']):
    found.append((str(x.get('date_publish',''))[:10],nums,x.get('title')))
 except: pass
seen=set()
for d,nums,t in sorted(found,reverse=True):
 key=(d,tuple(nums),t)
 if key not in seen:
  seen.add(key); print(d,','.join(nums),'|',t)
